class ExtensionCounter:
    def __init__(self, text):
        self.text = text

    def extension_counts(self):
        counts = {}
        i = 0
        while i < len(self.text):
            if self.text[i] == '.':
                j = i + 1
                while j < len(self.text) and self.text[j] != ' ' and self.text[j] != '\n':
                    j += 1
                ext = self.text[i+1:j]
                if ext:
                    upper = sum(1 for c in ext if c.isupper())
                    lower = sum(1 for c in ext if c.islower())
                    diff = upper - lower
                    counts[ext] = diff
                i = j
            else:
                i += 1
        return counts

    def best_extension(self):
        counts = self.extension_counts()
        if not counts:
            return None
        best = max(counts.items(), key=lambda kv: kv[1])
        return best[0]

if __name__ == "__main__":
    # Example usage: read from stdin, extract extension with highest uppercase-lowercase difference
    import sys
    text = sys.stdin.read()
    ec = ExtensionCounter(text)
    print(ec.best_extension())

