class Strongest_Extension:
    @staticmethod
    def strongest(class_name, extensions):
        def strength(s):
            CAP = 0
            SM = 0
            for ch in s:
                if 'A' <= ch <= 'Z':
                    CAP += 1
                elif 'a' <= ch <= 'z':
                    SM += 1
            return CAP - SM

        # Compute maximum strength among extensions
        max_strength = max(strength(ext) for ext in extensions)

        # Return first extension with maximum strength, concatenated with class name
        for ext in extensions:
            if strength(ext) == max_strength:
                return f"{class_name}.{ext}"

        return None  # In case no extensions provided or something unexpected

