import sqlite3

class DBWrapper:
    def __init__(self, path: str = ":memory:"):
        self.conn = sqlite3.connect(path)
        self.conn.execute("""
            CREATE TABLE IF NOT EXISTS blobs (
                id INTEGER PRIMARY KEY,
                data BLOB NOT NULL
            )
        """)
        self.conn.commit()

    def put(self, blob_id: int, data: bytes) -> None:
        with self.conn:
            self.conn.execute(
                "INSERT OR REPLACE INTO blobs (id, data) VALUES (?, ?)",
                (blob_id, data)
            )

    def get(self, blob_id: int) -> bytes:
        cur = self.conn.cursor()
        cur.execute("SELECT data FROM blobs WHERE id = ?", (blob_id,))
        row = cur.fetchone()
        if row is None:
            raise KeyError(f"No blob found with id {blob_id}")
        return row[0]

    def close(self) -> None:
        self.conn.close()


